#pragma once
#include <cmath>
#include <fstream>
#include <iomanip>
#include <unordered_map>

struct SEGameScene { std::int64_t id=0,width=640,height=480;std::string title="SE Scene",background="#111";std::vector<std::string> drawing,scripts; };
inline std::unordered_map<std::int64_t,SEGameScene>& se_game_scenes(){static std::unordered_map<std::int64_t,SEGameScene> value;return value;}
inline std::int64_t& se_game_next_id(){static std::int64_t id=1;return id;}
inline SEGameScene& se_game_scene(const SEAny& value){auto id=se_any_cast<std::int64_t>(value);auto it=se_game_scenes().find(id);if(it==se_game_scenes().end())throw std::runtime_error("Unknown game scene.");return it->second;}
inline double se_game_number(const SEAny& value){if(auto n=std::get_if<double>(&value))return *n;if(auto n=std::get_if<std::int64_t>(&value))return static_cast<double>(*n);throw std::runtime_error("Game API expects a number.");}
inline std::int64_t se_game_integer(const SEAny& value){if(auto n=std::get_if<std::int64_t>(&value))return *n;throw std::runtime_error("Game API expects Int.");}
inline std::string se_game_text(const SEAny& value){if(auto s=std::get_if<std::string>(&value))return *s;throw std::runtime_error("Game API expects Text.");}
inline bool se_game_bool(const SEAny& value){if(auto b=std::get_if<bool>(&value))return *b;throw std::runtime_error("Game API expects Bool.");}
inline std::string se_game_js(const std::string& value){std::string out;for(unsigned char c:value){switch(c){case '\\':out+="\\\\";break;case '"':out+="\\\"";break;case '\n':out+="\\n";break;case '\r':out+="\\r";break;case '\t':out+="\\t";break;default:if(c<32){std::ostringstream q;q<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<static_cast<int>(c);out+=q.str();}else out+=static_cast<char>(c);}}return out;}
inline std::string se_game_num(double value){if(!std::isfinite(value))throw std::runtime_error("Game coordinates must be finite.");std::ostringstream out;out<<std::setprecision(15)<<value;return out.str();}
inline void se_game_script(SEGameScene& scene,const std::string& script){scene.scripts.push_back(script);}
inline std::string se_game_html(const SEGameScene& scene){std::ostringstream out;out<<"<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>"<<se_template_escape(scene.title)<<"</title><style>html,body{margin:0;width:100%;height:100%;background:#111;display:grid;place-items:center}canvas{max-width:100vw;max-height:100vh}</style></head><body><canvas id=\"game\" width=\""<<scene.width<<"\" height=\""<<scene.height<<"\"></canvas><script>const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),SEGame=window.SEGame?" "?=( {sprites:new Map(),sounds:new Map(),camera:{x:0,y:0},particles:[]} );canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();SEGame.mouse={x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};});ctx.fillStyle=\""<<se_game_js(scene.background)<<"\";ctx.fillRect(0,0,canvas.width,canvas.height);";for(const auto& command:scene.drawing)out<<command;for(const auto& script:scene.scripts)out<<script;out<<"</script></body></html>";return out.str();}
inline std::string se_game_ident(const SEAny& value){return se_game_js(se_game_text(value));}
inline void se_game_show(const SEGameScene& scene){
  auto path=std::filesystem::temp_directory_path()/("se-game-"+std::to_string(scene.id)+".html");
  {std::ofstream out(path,std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("Could not create a game display file.");auto html=se_game_html(scene);out.write(html.data(),static_cast<std::streamsize>(html.size()));if(!out)throw std::runtime_error("Could not write the game display file.");}
#ifdef _WIN32
  (void)se_process_argv(SEList<std::string>{"cmd","/c","start","",path.string()});
#elif __APPLE__
  (void)se_process_argv(SEList<std::string>{"open",path.string()});
#else
  (void)se_process_argv(SEList<std::string>{"xdg-open",path.string()});
#endif
}
inline SEAny se_game_op_impl(const std::string& module,const std::string& op,const SEList<SEAny>& a){
  auto need=[&](std::size_t count){if(a.size()!=count)throw std::runtime_error(module+"."+op+" received the wrong number of arguments.");};
  auto idx=[&](std::size_t i)->const SEAny&{if(i>=a.size())throw std::runtime_error("Missing game API argument.");return a[i];};
  auto sceneop=module=="game"||module=="gui"||module=="window"||module=="canvas"||module=="scene";
  if(sceneop&&op=="new"){need(3);auto w=se_game_integer(idx(0)),h=se_game_integer(idx(1));if(w<1||h<1||w>8192||h>8192)throw std::runtime_error("Game scene dimensions must be 1..8192.");SEGameScene s;s.id=se_game_next_id()++;s.width=w;s.height=h;s.title=se_game_text(idx(2));se_game_scenes()[s.id]=s;return SEAny(s.id);}
  if(module=="physics"||module=="collision"||module=="game"){
    if(op=="rect_hit"){need(8);auto x=se_game_number(idx(0)),y=se_game_number(idx(1)),w=se_game_number(idx(2)),h=se_game_number(idx(3)),x2=se_game_number(idx(4)),y2=se_game_number(idx(5)),w2=se_game_number(idx(6)),h2=se_game_number(idx(7));return SEAny(x<x2+w2&&x+w>x2&&y<y2+h2&&y+h>y2);}
    if(op=="circle_hit"){need(6);auto dx=se_game_number(idx(0))-se_game_number(idx(3)),dy=se_game_number(idx(1))-se_game_number(idx(4)),r=se_game_number(idx(2))+se_game_number(idx(5));return SEAny(dx*dx+dy*dy<=r*r);}
    if(op=="distance"){need(4);return SEAny(std::hypot(se_game_number(idx(2))-se_game_number(idx(0)),se_game_number(idx(3))-se_game_number(idx(1))));}
    if(op=="vector"){need(2);return SEAny(SEList<SEAny>{SEAny(se_game_number(idx(0))),SEAny(se_game_number(idx(1)))});}
  }
  if(op=="background"){need(2);auto& s=se_game_scene(idx(0));s.background=se_game_text(idx(1));return SEAny{};}
  if(op=="clear"){need(1);auto& s=se_game_scene(idx(0));s.drawing.clear();s.scripts.clear();return SEAny{};}
  if(op=="rect"){need(7);auto& s=se_game_scene(idx(0));auto fill=se_game_bool(idx(6));auto color=se_game_ident(idx(5));std::ostringstream q;q<<"ctx."<<(fill?"fillStyle":"strokeStyle")<<"=\""<<color<<"\";ctx."<<(fill?"fillRect":"strokeRect")<<"("<<se_game_num(se_game_number(idx(1)))<<","<<se_game_num(se_game_number(idx(2)))<<","<<se_game_num(se_game_number(idx(3)))<<","<<se_game_num(se_game_number(idx(4)))<<");";s.drawing.push_back(q.str());return SEAny{};}
  if(op=="circle"){need(6);auto& s=se_game_scene(idx(0));auto fill=se_game_bool(idx(5));auto color=se_game_ident(idx(4));std::ostringstream q;q<<"ctx.beginPath();ctx.arc("<<se_game_num(se_game_number(idx(1)))<<","<<se_game_num(se_game_number(idx(2)))<<","<<se_game_num(se_game_number(idx(3)))<<",0,Math.PI*2);ctx."<<(fill?"fillStyle":"strokeStyle")<<"=\""<<color<<"\";ctx."<<(fill?"fill":"stroke")<<"();";s.drawing.push_back(q.str());return SEAny{};}
  if(op=="line"){need(7);auto& s=se_game_scene(idx(0));std::ostringstream q;q<<"ctx.beginPath();ctx.moveTo("<<se_game_num(se_game_number(idx(1)))<<","<<se_game_num(se_game_number(idx(2)))<<");ctx.lineTo("<<se_game_num(se_game_number(idx(3)))<<","<<se_game_num(se_game_number(idx(4)))<<");ctx.strokeStyle=\""<<se_game_ident(idx(5))<<"\";ctx.lineWidth="<<se_game_num(se_game_number(idx(6)))<<";ctx.stroke();";s.drawing.push_back(q.str());return SEAny{};}
  if(op=="text"){need(6);auto& s=se_game_scene(idx(0));std::ostringstream q;q<<"ctx.fillStyle=\""<<se_game_ident(idx(5))<<"\";ctx.font=\""<<se_game_num(se_game_number(idx(4)))<<"px sans-serif\";ctx.fillText(\""<<se_game_js(se_game_text(idx(1)))<<"\","<<se_game_num(se_game_number(idx(2)))<<","<<se_game_num(se_game_number(idx(3)))<<");";s.drawing.push_back(q.str());return SEAny{};}
  if(op=="html"){need(1);return SEAny(se_game_html(se_game_scene(idx(0))));}
  if(op=="save"){need(2);auto path=se_game_text(idx(1));std::ofstream out(path,std::ios::binary);if(!out){auto parent=std::filesystem::path(path).parent_path();if(!parent.empty())std::filesystem::create_directories(parent);out.clear();out.open(path,std::ios::binary|std::ios::trunc);}if(!out)throw std::runtime_error("Could not save game HTML.");auto html=se_game_html(se_game_scene(idx(0)));out.write(html.data(),static_cast<std::streamsize>(html.size()));if(!out)throw std::runtime_error("Could not write game HTML.");return SEAny{};}
  if(op=="show"){need(1);se_game_show(se_game_scene(idx(0)));return SEAny{};}
  if((module=="window"||module=="game")&&op=="fullscreen"){need(1);se_game_script(se_game_scene(idx(0)),"canvas.addEventListener('dblclick',()=>canvas.requestFullscreen?.());");return SEAny{};}
  if(module=="game"&&op=="script"){need(2);se_game_script(se_game_scene(idx(0)),se_game_text(idx(1)));return SEAny{};}
  if(module=="game"&&op=="camera"||module=="mouse"&&op=="camera"||module=="physics"&&op=="camera"){need(3);auto x=se_game_num(se_game_number(idx(1))),y=se_game_num(se_game_number(idx(2)));se_game_script(se_game_scene(idx(0)),"ctx.translate(-"+x+",-"+y+");");return SEAny{};}
  if((module=="physics"||module=="game")&&op=="particles"){need(6);auto count=se_game_integer(idx(3));if(count<0||count>10000)throw std::runtime_error("Particle count must be 0..10000.");std::ostringstream q;q<<"for(let i=0;i<"<<count<<";i++){ctx.fillStyle=\""<<se_game_ident(idx(4))<<"\";ctx.fillRect("<<se_game_num(se_game_number(idx(1)))<<"+(Math.random()-.5)*"<<se_game_num(se_game_number(idx(5)))<<","<<se_game_num(se_game_number(idx(2)))<<"+(Math.random()-.5)*"<<se_game_num(se_game_number(idx(5)))<<",3,3);}";se_game_scene(idx(0)).drawing.push_back(q.str());return SEAny{};}
  if((module=="physics"||module=="game"||module=="sprite"||module=="animation"||module=="input"||module=="keyboard"||module=="mouse")&&(op=="velocity"||op=="move"||op=="position"||op=="key_move"||op=="follow_mouse"||op=="animate")){
    auto& s=se_game_scene(idx(0));
    if(op=="animate"){need(2);auto fps=se_game_number(idx(1));if(fps<=0||fps>240)throw std::runtime_error("Animation fps must be between 0 and 240.");std::ostringstream js;js<<"{let last=performance.now();function seFrame(now){const dt=Math.min((now-last)/1000,0.1);last=now;ctx.fillStyle=\""<<se_game_js(s.background)<<"\";ctx.fillRect(0,0,canvas.width,canvas.height);for(const p of SEGame.sprites.values()){p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.img&&p.img.complete)ctx.drawImage(p.img,p.x,p.y,p.w,p.h);else if(p.color){ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.w,p.h);}}requestAnimationFrame(seFrame);}requestAnimationFrame(seFrame);}";se_game_script(s,js.str());return SEAny{};}
    if(op=="follow_mouse"){need(2);auto name=se_game_ident(idx(1));se_game_script(s,"canvas.addEventListener('mousemove',()=>{const p=SEGame.sprites.get(\""+name+"\");if(p&&SEGame.mouse){p.x=SEGame.mouse.x-p.w/2;p.y=SEGame.mouse.y-p.h/2;}});");return SEAny{};}
    if(op=="key_move"){need(5);auto name=se_game_ident(idx(1)),key=se_game_ident(idx(2));auto dx=se_game_num(se_game_number(idx(3))),dy=se_game_num(se_game_number(idx(4)));se_game_script(s,"addEventListener('keydown',e=>{if(e.key===\""+key+"\"){const p=SEGame.sprites.get(\""+name+"\");if(p){p.x+="+dx+";p.y+="+dy+";}}});");return SEAny{};}
    need(4);auto name=se_game_ident(idx(1));auto x=se_game_num(se_game_number(idx(2))),y=se_game_num(se_game_number(idx(3)));std::string js;
    if(op=="position")js="{const p=SEGame.sprites.get(\""+name+"\");if(p){p.x="+x+";p.y="+y+";}}";
    else if(op=="move")js="{const p=SEGame.sprites.get(\""+name+"\");if(p){p.x+="+x+";p.y+="+y+";}}";
    else js="{const p=SEGame.sprites.get(\""+name+"\");if(p){p.vx="+x+";p.vy="+y+";}}";
    se_game_script(s,js);return SEAny{};
  }
  if((module=="sound"||module=="audio"||module=="game")&&(op=="sound"||op=="play"||op=="stop")){if(op=="sound")need(3);else if(op=="play")need(4);else need(2);auto& s=se_game_scene(idx(0));if(op=="sound")se_game_script(s,"window.SEAudio?window.SEAudio:window.SEAudio={};window.SEAudio[\""+se_game_ident(idx(1))+"\"]=new Audio(\""+se_game_ident(idx(2))+"\");");else if(op=="play"){auto volume=se_game_number(idx(3));if(volume<0||volume>1)throw std::runtime_error("Audio volume must be 0..1.");se_game_script(s,"{const a=window.SEAudio?.[\""+se_game_ident(idx(1))+"\"];if(a){a.loop="+(se_game_bool(idx(2))?"true":"false")+";a.volume="+se_game_num(volume)+";a.play();}}");}else se_game_script(s,"{const a=window.SEAudio?.[\""+se_game_ident(idx(1))+"\"];if(a){a.pause();a.currentTime=0;}}");return SEAny{};}
  if((module=="video"&&op=="add")||(module=="camera"&&op=="start")){need(module=="video"?6:5);auto& s=se_game_scene(idx(0));std::size_t p=module=="video"?2:1;auto x=se_game_num(se_game_number(idx(p))),y=se_game_num(se_game_number(idx(p+1))),w=se_game_num(se_game_number(idx(p+2))),h=se_game_num(se_game_number(idx(p+3)));std::string style="position:absolute;left:"+x+"px;top:"+y+"px;width:"+w+"px;height:"+h+"px";std::string js;if(module=="video")js="{const v=document.createElement('video');v.src=\""+se_game_ident(idx(1))+"\";v.autoplay=true;v.muted=true;v.style.cssText=\""+style+"\";document.body.appendChild(v);}";else js="navigator.mediaDevices?.getUserMedia({video:true}).then(stream=>{window.SEVideo=document.createElement('video');SEVideo.srcObject=stream;SEVideo.autoplay=true;SEVideo.style.cssText=\""+style+"\";document.body.appendChild(SEVideo);});";se_game_script(s,js);return SEAny{};}
  if((module=="video"||module=="camera")&&op=="stop"){need(1);se_game_script(se_game_scene(idx(0)),"document.querySelectorAll('video').forEach(v=>{v.pause();v.srcObject?.getTracks().forEach(t=>t.stop());v.remove();});");return SEAny{};}
  if((module=="sprite"||module=="image"||module=="game")&&(op=="image"||op=="sprite"||op=="sprite_color")){auto& s=se_game_scene(idx(0));if(op=="sprite_color"){need(7);auto name=se_game_ident(idx(1));auto x=se_game_num(se_game_number(idx(2))),y=se_game_num(se_game_number(idx(3))),w=se_game_num(se_game_number(idx(4))),h=se_game_num(se_game_number(idx(5))),color=se_game_ident(idx(6));se_game_script(s,"SEGame.sprites.set(\""+name+"\",{x:"+x+",y:"+y+",w:"+w+",h:"+h+",vx:0,vy:0,color:\""+color+"\"});ctx.fillStyle=\""+color+"\";ctx.fillRect("+x+","+y+","+w+","+h+");");}else{bool named=op=="sprite";need(named?7:6);auto name=named?se_game_ident(idx(1)):std::string("image");std::size_t url=named?2:1,at=named?3:2;auto image_url=se_game_ident(idx(url)),x=se_game_num(se_game_number(idx(at))),y=se_game_num(se_game_number(idx(at+1))),w=se_game_num(se_game_number(idx(at+2))),h=se_game_num(se_game_number(idx(at+3)));se_game_script(s,"{const im=new Image();im.src=\""+image_url+"\";const p={x:"+x+",y:"+y+",w:"+w+",h:"+h+",vx:0,vy:0,img:im};SEGame.sprites.set(\""+name+"\",p);im.onload=()=>ctx.drawImage(im,p.x,p.y,p.w,p.h);}");}return SEAny{};}

  throw std::runtime_error("Unsupported graphics API operation: "+module+"."+op);
}
template<class... Args> inline SEAny se_game_op(const std::string& module,const std::string& op,const Args&... args){return se_game_op_impl(module,op,SEList<SEAny>{SEAny(args)...});}
